/// Entries for a chassis code, or empty if not in the catalog.
pub fn entries_for(chassis: &str) -> &'static [CatEntry] {
    CATALOG.iter().find(|c| c.chassis == chassis).map(|c| c.entries).unwrap_or(&[])
}
